def run_react(steps, observe):
    results = []
    for action in steps:
        try:
            got = observe(action)
        except Exception as error:
            raise ValueError('observe failed: ' + str(error))
        if got is None:
            raise ValueError('observe returned None')
        results.append(got)
        if got == 'stop':
            return [results, len(results)]
    return [results, len(results)]

